let communityCategory='Tümü',careFilter='all',followReturnList=false,blockedProfiles=[];let lastDetailView='',mobileKeyboardOpen=false;let mobileChatOpen=false,chatFilter='primary',profilePostsTab='media';let followListId='',followListMode='followers',phonePushActive=null;let sb,me,view='home',articleId='',personId='',profileId='',selectedPostId='',feedFilter='new',feedMediaMode='media',exploreTab='all',exploreAnimal='Tümü',exploreSort='latest',kbFilter='Tümü',kbSearch='',search='',authMode='login',busy=false;
