function showAuth(msg='') {starter();appRoot.classList.add('hidden');authRoot.classList.remove('hidden');let isSign=authMode==='signup',reset=authMode==='reset';authRoot.innerHTML=`<div class="auth-shell"><aside class="auth-story" aria-label="Patiyiz topluluğu"><div class="auth-story-top"><span class="auth-story-icon" aria-hidden="true"><svg viewBox="0 0 64 64" fill="currentColor" xmlns="http://www.w3.org/2000/svg"><ellipse cx="13" cy="19" rx="6" ry="9" transform="rotate(-22 13 19)"/><ellipse cx="27" cy="11" rx="6" ry="9" transform="rotate(-7 27 11)"/><ellipse cx="43" cy="14" rx="6" ry="9" transform="rotate(15 43 14)"/><ellipse cx="54" cy="27" rx="5" ry="8" transform="rotate(32 54 27)"/><path d="M33 26c-6-1-9 5-14 10-5 4-10 10-7 17 3 8 11 7 19 4 4-2 9-1 14 1 9 3 16-2 13-10-2-6-8-10-12-15-4-5-7-7-13-7Z"/></svg></span><strong>patiyiz</strong><span class="auth-story-topline">BİRLİKTE DAHA GÜZEL</span></div><div class="auth-story-bottom"><span class="auth-story-label"><span class="auth-story-dot"></span> HAYVANSEVERLERİN DÜNYASI</span><h2>Onların hikâyesi,<br><em>bizim dünyamız.</em></h2><p>Patili dostlarınla anılarını paylaş, yeni arkadaşlıklar kur ve merak ettiklerini keşfet.</p></div></aside><div class="auth-pane"><div class="auth-card"><div class="auth-brand"><div class="brand-icon auth-matching-logo" aria-label="Patiyiz logosu"><img class="patiyiz-chosen-logo" src="patiyiz-selected-logo.svg" alt="Patiyiz"></div><div><h1>patiyiz</h1><p>Hayvanseverlerin buluşma noktası</p></div></div>${reset?'':`<div class="auth-tabs"><button data-auth="login" class="${authMode==='login'?'active':''}">Giriş yap</button><button data-auth="signup" class="${isSign?'active':''}">Kayıt ol</button></div>`}<div class="auth-eyebrow">🐾 PATİYİZ'E HOŞ GELDİN</div><h2>${reset?'Şifreni yenileyelim':isSign?'Aramıza katıl':'Yeniden merhaba!'}</h2><p class="auth-sub">${reset?'E-posta adresini yaz, sana şifre yenileme bağlantısı gönderelim.':isSign?'Patili dostunla yeni bir dünyaya adım at. Üyelik ücretsiz.':'Patili dostların ve güzel hikâyeler burada seni bekliyor.'}</p>${msg?`<div class="pati-note">${esc(msg)}</div>`:''}<form id="auth-form">${isSign?`<div class="pati-field"><label for="display_name">Adın</label><input id="display_name" name="display_name" required minlength="2" maxlength="70" autocomplete="name" placeholder="Ad ve soyad"></div>`:''}<div class="pati-field"><label for="email">E-posta</label><input id="email" name="email" type="email" required autocomplete="email" placeholder="ornek@eposta.com"></div>${reset?'':`<div class="pati-field"><label for="password">Şifre</label><input id="password" name="password" type="password" required minlength="6" autocomplete="${isSign?'new-password':'current-password'}" placeholder="Şifreni gir"></div>`}<span class="pati-auth-terms">${isSign?'<label><input name="age_accepted" type="checkbox" value="yes" required> 18 yaşını doldurduğumu onaylıyorum.</label><label><input name="terms_accepted" type="checkbox" value="yes" required> <a href="terms.html" target="_blank" rel="noopener">Kullanım Şartlarını</a> ve <a href="privacy.html" target="_blank" rel="noopener">Gizlilik Politikasını</a> okudum, kabul ediyorum.</label>':'<a href="privacy.html" target="_blank" rel="noopener">Gizlilik Politikası</a> · <a href="terms.html" target="_blank" rel="noopener">Kullanım Şartları</a>'}</span><button class="primary-btn auth-submit" type="submit"><span>${reset?'Sıfırlama bağlantısı gönder':isSign?'Ücretsiz hesap oluştur':'Giriş yap'}</span><span aria-hidden="true">→</span></button></form><div class="auth-bottom"><button class="btn-link" data-auth="${reset?'login':'reset'}">${reset?'← Girişe dön':'Şifremi unuttum'}</button></div><p class="small-note"><span aria-hidden="true">🔒</span> E-posta doğrulama ve güvenli giriş. Gelen kutunu, gerekirse spam klasörünü kontrol et.</p></div></div></div>`}
async function checkAdmin(){if(!me||!sb){isAdmin=false;return}try{const {data,error}=await sb.rpc('patiyiz_is_admin');isAdmin=!error&&data===true}catch(e){isAdmin=false}if(!appRoot.classList.contains('hidden')){navRender();if(view==='settings')render()}}
function showApp(){starter();authRoot.classList.add('hidden');appRoot.classList.remove('hidden');navigate(view);startLive();routePendingNotification();checkAdmin();if(!patiyizDeferredLoading){const userId=me.id;patiyizDeferredLoading=new Promise(resolve=>setTimeout(resolve,1200)).then(async()=>{if(me?.id!==userId)return;await load('deferred');if(me?.id!==userId)return;navRender();if(!document.activeElement?.matches('input,textarea,[contenteditable]'))render()}).catch(e=>console.warn('Arka plan yüklemesi:',e)).finally(()=>{patiyizDeferredLoading=null})}}
const authBusy=async(fn)=>{try{let r=await fn();if(r.error)throw r.error;return r.data}catch(e){notify(friendly(e),true);return null}};
authRoot.addEventListener('click',e=>{let b=e.target.closest('[data-auth]');if(!b)return;authMode=b.dataset.auth;showAuth()});
authRoot.addEventListener('submit',async(e)=>{if(e.target.id!=='auth-form')return;e.preventDefault();let fd=new FormData(e.target), email=String(fd.get('email')||'').trim(), password=String(fd.get('password')||'');if(authMode==='reset'){let res=await authBusy(()=>sb.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname}));if(res!==null)showAuth('Şifre yenileme e-postasını kontrol edin.');return}if(authMode==='signup'){if(fd.get('age_accepted')!=='yes')return notify('Patiyiz şu anda 18 yaş ve üzeri kullanıcılar içindir.',true);if(fd.get('terms_accepted')!=='yes')return notify('Kayıt olmak için şartları kabul etmelisin.',true);let res=await authBusy(()=>sb.auth.signUp({email,password,options:{emailRedirectTo:location.origin+location.pathname,data:{display_name:String(fd.get('display_name')||'Patiyiz Üyesi')}}}));if(res){if(res.session){me=res.user;await load('initial');showApp()}else{authMode='login';showAuth('Hesabın oluşturuldu. Gelen e-postadan adresini doğrula, ardından giriş yap.')}}return}let res=await authBusy(()=>sb.auth.signInWithPassword({email,password}));if(res){me=res.user;await load('initial');showApp()}});
function header(title,subtitle='',cta=''){return `<div class="page-intro"><div><div class="hello">PATİYİZ TOPLULUĞU</div><h1 class="page-title">${esc(title)}</h1>${subtitle?`<p style="font-size:12px;color:#7e9384;margin:5px 0 0">${esc(subtitle)}</p>`:''}</div><div class="top-actions">${cta}</div></div>`}

// Realtime: subscribe to authorized changes only. A debounce prevents duplicate refreshes.
function stopLive(){if(liveReloadTimer)clearTimeout(liveReloadTimer);liveReloadTimer=null;if(liveChannel&&sb)sb.removeChannel(liveChannel);liveChannel=null;liveInitialized=false;liveUserId=null}
async function refreshLiveTables(){const result=await Promise.all([sb.from('messages').select('*').order('created_at',{ascending:false}).limit(pageLimits.messages||150),sb.from('notifications').select('*').order('created_at',{ascending:false}).limit(pageLimits.notifications||150)]);if(result[0].error)throw result[0].error;if(result[1].error)throw result[1].error;data.messages=result[0].data||[];data.notifications=result[1].data||[]}
function queueLiveUpdate(){if(liveReloadTimer)clearTimeout(liveReloadTimer);liveReloadTimer=setTimeout(async()=>{if(!me)return;const oldMessageCount=data.messages.filter(x=>x.receiver_id===me.id&&!x.read_at).length;const oldNoticeCount=data.notifications.filter(x=>x.owner_id===me.id&&!x.read).length;const previousConversation=view==='messages'?data.messages.filter(x=>(x.sender_id===me.id&&x.receiver_id===personId)||(x.sender_id===personId&&x.receiver_id===me.id)).map(x=>x.id+'_'+x.read_at).join('|'):'';await refreshLiveTables();navRender();if(view==='messages'){const nextConversation=data.messages.filter(x=>(x.sender_id===me.id&&x.receiver_id===personId)||(x.sender_id===personId&&x.receiver_id===me.id)).map(x=>x.id+'_'+x.read_at).join('|');if(previousConversation!==nextConversation){const field=$('#message-form input[name="body"]');const draft=field?.value||'',focus=document.activeElement===field,position=field?.selectionStart??draft.length;render();const next=$('#message-form input[name="body"]');if(next){next.value=draft;if(focus){next.focus();next.setSelectionRange(position,position)}}}}else render();const unread=data.messages.filter(x=>x.receiver_id===me.id&&!x.read_at).length;const notices=data.notifications.filter(x=>x.owner_id===me.id&&!x.read).length;if(unread>oldMessageCount||notices>oldNoticeCount)notify('Yeni bir Patiyiz bildirimin var 🐾');if(view==='messages')markConversationRead();},250)}
function startLive(){if(!me||!sb)return;if(liveUserId===me.id&&liveChannel)return;stopLive();liveUserId=me.id;
 liveChannel=sb.channel('patiyiz-live-'+me.id)
 .on('postgres_changes',{event:'*',schema:'public',table:'messages',filter:'receiver_id=eq.'+me.id},queueLiveUpdate)
 .on('postgres_changes',{event:'*',schema:'public',table:'messages',filter:'sender_id=eq.'+me.id},queueLiveUpdate)
 .on('postgres_changes',{event:'INSERT',schema:'public',table:'notifications',filter:'owner_id=eq.'+me.id},queueLiveUpdate)
 .subscribe(status=>{if(status==='SUBSCRIBED')liveInitialized=true;});
}
async function markConversationRead(){if(!me||view!=='messages'||!personId)return;const unread=data.messages.filter(x=>x.sender_id===personId&&x.receiver_id===me.id&&!x.read_at);if(!unread.length)return;
 const now=new Date().toISOString();const ids=unread.map(x=>x.id);const r=await sb.from('messages').update({read_at:now}).in('id',ids).eq('receiver_id',me.id);if(r.error){console.warn('Okundu bilgisi kaydedilemedi',r.error.message);return}
 unread.forEach(x=>x.read_at=now);navRender();if(view==='messages')render();
}
function unreadCounts(){const hidden=new Set(data.messageHidden.filter(x=>x.user_id===me?.id).map(x=>x.message_id));return {messages:data.messages.filter(x=>x.receiver_id===me?.id&&!x.read_at&&!blocked.has(x.sender_id)&&!hidden.has(x.id)).length,notifications:data.notifications.filter(x=>x.owner_id===me?.id&&!x.read&&!blocked.has(x.actor_id)).length}}
function unreadMessageSources(){const hidden=new Set(data.messageHidden.filter(x=>x.user_id===me?.id).map(x=>x.message_id));const messages=data.messages.filter(x=>x.receiver_id===me?.id&&!x.read_at&&!blocked.has(x.sender_id)&&!hidden.has(x.id));const tally=new Map();for(const m of messages)tally.set(m.sender_id,(tally.get(m.sender_id)||0)+1);return [...tally].sort((a,b)=>b[1]-a[1]).map(([id,count])=>({id,count,name:profile(id).display_name}))}
const countBadge=n=>n?`<span class="pati-count-badge" aria-label="${n} okunmamış">${n>99?'99+':n}</span>`:'';
function navRender(){const fab=$('#app-root>.mobile-fab');if(fab){const action=view==='community'?'question':view==='care'?'care-add':view==='lost'?'lost-add':view==='adoption'?'adoption-add':view==='home'?'compose':'';const label=view==='community'?'Topluluğa soru sor':view==='care'?'Bakım görevi ekle':view==='lost'?'Kayıp ilanı oluştur':view==='adoption'?'Sahiplendirme ilanı oluştur':'Paylaşım oluştur';fab.hidden=!action;fab.style.display=action?'':'none';if(action){fab.dataset.action=action;fab.setAttribute('aria-label',label);fab.setAttribute('title',label)}}const sideCreate=$('.nav-create');if(sideCreate){const action=view==='community'?'question':view==='care'?'care-add':view==='lost'?'lost-add':view==='home'?'compose':'';sideCreate.hidden=!action;sideCreate.style.display=action?'':'none';if(action){sideCreate.dataset.action=action;sideCreate.innerHTML=ico('plus')+(view==='community'?' Soru sor':view==='care'?' Görev ekle':view==='lost'?' İlan oluştur':view==='adoption'?' Sahiplendirme ilanı':' Yeni paylaşım')}}const counts=unreadCounts();const topBell=$('#pati-header-notifications');if(topBell){topBell.innerHTML=ico('bell')+countBadge(counts.notifications);topBell.classList.toggle('active',view==='notifications')}let navItem=([id,label,icon])=>`<button class="nav-link ${view===id?'active':''}" data-view="${id}">${ico(icon)}${label}${id==='messages'?countBadge(counts.messages):id==='notifications'?countBadge(counts.notifications):''}</button>`;$('#desktop-nav').innerHTML=nav.map(navItem).join('')+(isAdmin?`<button class="nav-link patiyiz-admin-nav" type="button" data-action="open-admin">${ico('shield')}Yönetim Paneli</button>`:'');$('#mobile-nav').innerHTML=[['home','Ana Sayfa','home'],['explore','Keşfet','compass'],['community','Topluluk','users'],['messages','Mesajlar','message']].map(([id,label,icon])=>`<button class="mobile-nav-btn ${view===id?'active':''}" data-view="${id}">${ico(icon)}<small>${label}</small>${id==='messages'?countBadge(counts.messages):''}</button>`).join('')+`<button type="button" class="mobile-nav-btn pati-profile-nav ${view==='profile'?'active':''}" data-view="profile" aria-label="Profilim">${avatar(current(),'s')}<small>Profil</small></button>`}
function side(){let p=current();rail.innerHTML=`<div class="pati-card"><div class="pati-profile-row">${avatar(p)}<div><strong>${esc(p.display_name)}</strong><small>@${esc(p.handle)}</small></div></div><div class="pati-actionbar">${button('Profilim','my-profile')}</div></div><div class="pati-card" style="margin-top:15px"><h3>Güvenli topluluk</h3><p>Şikâyet veya engelleme özelliğini kötüye kullanım halinde kullan. Acil hayvan sağlığı sorunlarında veteriner hekime başvur.</p></div>`}
let patiyizVideoObserver=null;
function setupFeedVideos(){
 if(patiyizVideoObserver){patiyizVideoObserver.disconnect();patiyizVideoObserver=null}
 const videos=[...document.querySelectorAll('#main-content .pati-video-frame video')];
 if(!videos.length)return;
 patiyizVideoObserver=new IntersectionObserver(entries=>{
  for(const entry of entries){const video=entry.target;
   if(entry.isIntersecting&&entry.intersectionRatio>=.35&&!document.hidden&&!video.dataset.userPaused){
    videos.forEach(other=>{if(other!==video)other.pause()});
    video.play().catch(()=>{});
   }else video.pause();
  }
 },{threshold:[0,.2,.35,.65]});
 videos.forEach(v=>patiyizVideoObserver.observe(v));
}
document.addEventListener('visibilitychange',()=>{if(document.hidden)document.querySelectorAll('.pati-post-video').forEach(v=>v.pause());else setupFeedVideos()});
function ensureViewData(to){const byView={community:[['questions','questions'],['replies','replies'],['question_votes','votes']],knowledge:[['kb_bookmarks','bookmarks']],lost:[['lost_reports','lost']],adoption:[['adoption_listings','adoption']],care:[['care_tasks','care']],messages:[['message_hidden','messageHidden']],profile:[['patiyiz_voice_comments','voiceComments']],blocked:[['user_blocks','blocks']]};const missing=(byView[to]||[]).filter(([table])=>!patiyizLoadedTables.has(table));if(!missing.length)return;const requestedView=to;Promise.all(missing.map(async([table,key])=>{const req=sb.from(table).select('*');const r=await req.limit(350);if(r.error)throw r.error;return[table,key,r.data||[]]})).then(results=>{if(!me)return;for(const[table,key,rows]of results){if(!patiyizLoadedTables.has(table)){data[key]=rows;patiyizLoadedTables.add(table)}}if(view===requestedView)render()}).catch(e=>console.warn('Bölüm verileri yüklenemedi:',e))}
function navigate(to){if(!allowed.includes(to))to='home';if(to==='profile'&&view!=='profile'&&view!=='follows-list'&&!followReturnList)lastDetailView=view;view=to;if(view==='blocked')loadBlockedNames();articleId='';search='';window.scrollTo(0,0);navRender();side();render();ensureViewData(view);if(view==='profile')requestAnimationFrame(()=>{window.scrollTo({top:0,left:0,behavior:'instant'});document.scrollingElement?.scrollTo(0,0)});if(view==='messages')markConversationRead()}
function userRow(id,small=''){let p=profile(id);return `<button type="button" class="pati-profile-row" data-action="view-user" data-id="${esc(id)}" aria-label="${esc(p.display_name)} profilini aç" style="border:0;background:transparent;padding:0;text-align:left;width:100%;cursor:pointer;color:inherit;font:inherit">${avatar(p)}<span><strong>${displayName(p)}</strong><small style="display:block">@${esc(p.handle)} ${small?`· ${esc(small)}`:''}</small></span></button>`}
function render(){try{({home:homePage,explore:explorePage,community:communityPage,knowledge:knowledgePage,lost:lostPage,adoption:adoptionPage,care:carePage,messages:messagesPage,notifications:notificationsPage,profile:profilePage,blocked:blockedPage,settings:settingsPage,'follows-list':followListPage}[view]||homePage)();setupFeedVideos()}catch(e){console.error(e);main.innerHTML=header('Bir hata oldu')+empty('Ekran açılamadı','Sayfayı yenile veya daha sonra tekrar dene.')}}
async function load(mode='all'){if(!me)return;if(mode==='all'){try{const p=await sb.rpc('patiyiz_has_premium');hasPremium=!p.error&&p.data===true}catch{hasPremium=false}}let specs=[['profiles','profiles',800],['pets','pets',600],['posts','posts',200],['post_likes','likes',2000],['post_saves','saves',2000],['comments','comments',1500],['patiyiz_voice_comments','voiceComments',1500],['comment_likes','commentLikes',3000],['follows','follows',2000],['questions','questions',150],['replies','replies',1500],['question_votes','votes',2000],['lost_reports','lost',300],['adoption_listings','adoption',300],['patiyiz_stories','stories',250],['care_tasks','care',500],['messages','messages',1000],['message_hidden','messageHidden',1000],['notifications','notifications',500],['kb_bookmarks','bookmarks',300],['user_blocks','blocks',500]];if(mode==='initial')specs=specs.filter(([table])=>['profiles','pets','posts','post_likes','post_saves','comments','follows','patiyiz_stories','messages','notifications','user_blocks'].includes(table));else if(mode==='deferred')specs=specs.filter(([table])=>!patiyizLoadedTables.has(table));
const results=await Promise.all(specs.map(async([table,key,limit])=>{const chunks=[];const size=250,cap=pageLimits[key]||5000;try{for(let start=0;start<cap;start+=size){let req=sb.from(table).select('*').range(start,Math.min(start+size-1,cap-1));if(['messages','notifications','comments','posts','replies','questions','lost_reports','patiyiz_voice_comments','patiyiz_stories','adoption_listings'].includes(table))req=req.order('created_at',{ascending:false});const r=await req;if(r.error)throw r.error;chunks.push(...(r.data||[]));if((r.data||[]).length<size)break;}if(pageLimits[key])pageMore[key]=chunks.length>=cap;else if(chunks.length>=cap)console.warn(table,'yükleme sınırına ulaştı');return[key,chunks]}catch(e){console.warn(table,'yüklenemedi:',e.message);return[key,data[key]||[]]}}));for(const [k,val]of results){data[k]=val;patiyizLoadedTables.add(({profiles:'profiles',pets:'pets',posts:'posts',likes:'post_likes',saves:'post_saves',comments:'comments',voiceComments:'patiyiz_voice_comments',commentLikes:'comment_likes',follows:'follows',questions:'questions',replies:'replies',votes:'question_votes',lost:'lost_reports',adoption:'adoption_listings',stories:'patiyiz_stories',care:'care_tasks',messages:'messages',messageHidden:'message_hidden',notifications:'notifications',bookmarks:'kb_bookmarks',blocks:'user_blocks'})[k])}liked=new Set(data.likes.filter(x=>x.user_id===me.id).map(x=>x.post_id));saved=new Set(data.saves.filter(x=>x.user_id===me.id).map(x=>x.post_id));followed=new Set(data.follows.filter(x=>x.follower_id===me.id).map(x=>x.followee_id));voted=new Set(data.votes.filter(x=>x.user_id===me.id).map(x=>x.question_id));favorites=new Set(data.bookmarks.filter(x=>x.user_id===me.id).map(x=>x.article_id));blocked=new Set(data.blocks.filter(x=>x.blocker_id===me.id).map(x=>x.blocked_id))}
async function refreshKeys(specs){
 const results=await Promise.all(specs.map(async([table,key])=>{const r=await sb.from(table).select('*').order('created_at',{ascending:false}).limit(key==='messages'?400:key==='notifications'?150:200);if(r.error)throw r.error;return[key,r.data||[]]}));
 for(const[k,rows]of results)data[k]=rows;
 navRender();render();
}
async function refresh(){await load();navRender();render();if(view==='blocked')loadBlockedNames()}
async function loadMore(key){pageLimits[key]=(pageLimits[key]||100)+150;await refresh()}
function postCard(p){let own=p.author_id===me.id,c=data.comments.filter(x=>x.post_id===p.id&&!blocked.has(x.author_id)),n=data.likes.filter(x=>x.post_id===p.id).length;let pet=data.pets.find(x=>x.id===p.pet_id);return `<article class="pati-card" style="margin-bottom:15px">${userRow(p.author_id,day(p.created_at))}${pet?`<p class="pati-tag">${petIcon(pet.species)} ${esc(pet.name)} · ${esc(pet.species)}</p>`:''}<p style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(p.body)}</p>${p.video_url?`<div class="pati-video-frame"><video class="pati-post-video" autoplay playsinline muted loop preload="metadata" src="${esc(p.video_url)}" aria-label="Paylaşım videosu"></video><button type="button" class="pati-video-sound" data-action="video-sound" aria-label="Sesi aç">${ico("volume-x")}</button></div>`:''}${p.image_url?`<div class="pati-doubletap-photo" data-post-id="${esc(p.id)}">${photo(p.image_url)}<span class="pati-heart-burst" aria-hidden="true">♥</span></div>`:''}<div class="pati-actionbar pati-social-actions"><button data-action="like" aria-label="Beğen" data-id="${p.id}" class="${liked.has(p.id)?'active':''}">${ico('heart')} <span>${n}</span></button><button data-action="comment" aria-label="Yorum yap" data-id="${p.id}">${ico('message-circle')} <span>${c.length+data.voiceComments.filter(x=>x.post_id===p.id).length}</span></button><button data-action="share-post" aria-label="Arkadaşına gönder" data-id="${p.id}">${ico('send')}</button><button data-action="save" aria-label="Kaydet" data-id="${p.id}" class="pati-save-action ${saved.has(p.id)?'active':''}">${ico('bookmark')}</button>${own?`<button data-action="edit-post" data-id="${p.id}">Düzenle</button><button class="danger" data-action="delete-post" data-id="${p.id}">Sil</button>`:`<button data-action="report" data-kind="post" data-id="${p.id}">Bildir</button>`}</div></article>`}
function openPost(id){const post=data.posts.find(p=>p.id===id);if(!post){notify('Bu paylaşım artık bulunamıyor.',true);navigate('notifications');return}if(blocked.has(post.author_id)){notify('Bu paylaşım görüntülenemiyor.',true);return}feedFilter='new';selectedPostId=id;navigate('home')}
let storyItems=[],storyIndex=0,storyTimer=null,storyLikes=[];
function closeStory(){clearTimeout(storyTimer);storyTimer=null;storyItems=[];document.getElementById('story-overlay')?.remove();document.body.classList.remove('story-fullscreen-open')}
async function recordStoryView(x){if(!me||x.author_id===me.id)return;try{const r=await sb.rpc('patiyiz_record_story_view',{p_story_id:x.id});if(r.error)console.warn('Hikâye görüntülemesi kaydedilemedi:',r.error.message)}catch(err){console.warn('Hikâye görüntüleme ağ hatası:',err)}}
async function showStoryViewers(){const x=storyItems[storyIndex];if(!x||x.author_id!==me.id)return;clearTimeout(storyTimer);const [vr,lr]=await Promise.all([sb.from('patiyiz_story_views').select('viewer_id,last_viewed_at').eq('story_id',x.id).order('last_viewed_at',{ascending:false}),sb.from('patiyiz_story_likes').select('user_id').eq('story_id',x.id)]);if(vr.error){notify('Görüntüleyenler yüklenemedi.',true);return}if(lr.error)console.warn('Hikâye beğenileri yüklenemedi:',lr.error.message);const liked=new Set((lr.data||[]).map(v=>v.user_id));const list=(vr.data||[]).map(v=>'<div class="story-view-user">'+avatar(profile(v.viewer_id),'s')+'<div><strong>'+displayName(profile(v.viewer_id))+'</strong><small>'+new Date(v.last_viewed_at).toLocaleString('tr-TR',{hour:'2-digit',minute:'2-digit',day:'numeric',month:'short'})+'</small></div>'+(liked.has(v.viewer_id)?'<span class="pati-story-view-like" title="Hikâyeni beğendi">♥</span>':'')+'</div>').join('');const sheet=document.getElementById('story-viewers-sheet');if(sheet){sheet.innerHTML='<header>Görüntüleyenler ('+(vr.data||[]).length+') · ♥ '+liked.size+' <button data-action="story-viewers-close">×</button></header>'+(list||'<p>Henüz görüntüleyen yok.</p>');sheet.hidden=false}}
function showStoryFrame(){const root=document.getElementById('story-overlay'),x=storyItems[storyIndex];if(!root||!x)return;const user=profile(x.author_id);recordStoryView(x);if(x.author_id!==me.id)void syncStoryLike(x.id);root.innerHTML='<div class="story-player"><div class="story-progress">'+storyItems.map((_,i)=>'<span class="story-track"><span class="'+(i===storyIndex?'story-playing':'')+'" style="width:'+(i<storyIndex?'100':'0')+'%"></span></span>').join('')+'</div><div class="story-player-head">'+avatar(user,'s')+'<strong>'+displayName(user)+'</strong><button data-action="story-close" aria-label="Kapat" class="story-close">×</button></div><img class="story-big-photo" src="'+esc(x.image_url)+'" alt="Hikâye">'+(x.caption?'<p class="story-caption">'+esc(x.caption)+'</p>':'')+'<button class="story-hit prev" data-action="story-prev" aria-label="Önceki"></button><button class="story-hit next" data-action="story-next" aria-label="Sonraki"></button>'+(x.author_id===me.id?'<button class="story-highlight-toggle" data-action="story-highlight-toggle" data-id="'+esc(x.id)+'">'+(x.is_highlight?'★ Sabitlendi':'☆ Sabitle')+'</button><button class="story-delete" data-action="story-delete" data-id="'+esc(x.id)+'">🗑 Sil</button><button class="story-viewers-button" data-action="story-viewers">👁 Hareketler</button>':'<button class="pati-story-like" data-action="story-like" data-id="'+esc(x.id)+'" aria-label="Hikâyeyi beğen">♡</button><button class="story-delete" data-action="report" data-kind="story" data-id="'+esc(x.id)+'">Bildir</button>')+'<div id="story-viewers-sheet" class="story-viewers-sheet" hidden></div></div>';storyTimer=setTimeout(()=>stepStory(1),6000)}
async function syncStoryLike(id){const r=await sb.from('patiyiz_story_likes').select('story_id').eq('story_id',id).eq('user_id',me.id).maybeSingle();const btn=document.querySelector('.pati-story-like[data-id="'+id+'"]');if(!r.error&&btn){btn.textContent=r.data?'♥':'♡';btn.classList.toggle('active',!!r.data)}}
async function toggleStoryLike(id){const btn=document.querySelector('.pati-story-like[data-id="'+id+'"]');if(!btn)return;btn.disabled=true;try{const liked=btn.classList.contains('active');const r=liked?await sb.from('patiyiz_story_likes').delete().eq('story_id',id).eq('user_id',me.id):await sb.from('patiyiz_story_likes').insert({story_id:id,user_id:me.id});if(r.error)throw r.error;btn.classList.toggle('active',!liked);btn.textContent=liked?'♡':'♥';}catch(e){notify('Hikâye beğenilemedi: '+friendly(e),true)}finally{btn.disabled=false}}
function storiesStrip(){const live=data.stories.filter(x=>new Date(x.expires_at).getTime()>Date.now()&&!blocked.has(x.author_id)).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));const seen=new Set(),people=[];for(const x of live)if(!seen.has(x.author_id)){seen.add(x.author_id);people.push(x)}const own=people.find(x=>x.author_id===me.id);return '<section class="stories-section"><div class="stories-heading"><strong>Hikâyeler</strong></div><div class="stories-strip"><div class="story-person story-own"><button class="story-own-photo '+(own?'has-story':'')+'" data-action="'+(own?'story-view':'story-create')+'" '+(own?'data-id="'+esc(me.id)+'"':'')+'>'+avatar(current(),'s')+'</button><button class="story-own-plus" data-action="story-create">+</button><small>'+(own?'Hikâyem':'Hikâye ekle')+'</small></div>'+people.filter(x=>x.author_id!==me.id).map(x=>'<button class="story-person" data-action="story-view" data-id="'+esc(x.author_id)+'"><span class="story-avatar">'+avatar(profile(x.author_id),'s')+'</span><small>'+esc(profile(x.author_id).display_name)+'</small></button>').join('')+'</div></section>'}
function openStory(id){const items=data.stories.filter(x=>x.author_id===id&&(new Date(x.expires_at).getTime()>Date.now()||x.is_highlight)).sort((a,b)=>new Date(a.created_at)-new Date(b.created_at));if(!items.length)return notify('Hikâye bulunamadı.');closeStory();storyItems=items;storyIndex=0;const layer=document.createElement('div');layer.id='story-overlay';layer.className='story-fullscreen';layer.setAttribute('role','dialog');layer.setAttribute('aria-modal','true');document.body.appendChild(layer);document.body.classList.add('story-fullscreen-open');showStoryFrame()}
function openHighlights(id){const items=data.stories.filter(x=>x.author_id===id&&x.is_highlight).sort((a,b)=>new Date(a.created_at)-new Date(b.created_at));if(!items.length)return notify('Öne çıkan hikâye bulunamadı.');closeStory();storyItems=items;storyIndex=0;const layer=document.createElement('div');layer.id='story-overlay';layer.className='story-fullscreen';document.body.appendChild(layer);document.body.classList.add('story-fullscreen-open');showStoryFrame()}
function stepStory(n){if(!storyItems.length)return;clearTimeout(storyTimer);if(document.getElementById('story-viewers-sheet')?.hidden===false&&n===1)return;const next=storyIndex+n;if(next<0){showStoryFrame();return}if(next>=storyItems.length){closeStory();return}storyIndex=next;showStoryFrame()}
function homePage(){let list=[...data.posts].filter(p=>!blocked.has(p.author_id)).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));if(feedFilter==='following')list=list.filter(x=>followed.has(x.author_id)||x.author_id===me.id);if(!selectedPostId)list=list.filter(p=>feedMediaMode==='media'?Boolean(p.image_url||p.video_url):!p.image_url&&!p.video_url);main.innerHTML=selectedPostId?(header('Paylaşım','Bildirimin ilgili olduğu paylaşım.',button('← Ana sayfaya dön','post-back'))+(list.find(p=>p.id===selectedPostId)?postCard(list.find(p=>p.id===selectedPostId)):empty('Paylaşım bulunamadı'))):storiesStrip()+`<div class="pati-feed-switch" role="tablist" aria-label="Paylaşım akışları"><button type="button" role="tab" aria-selected="${feedMediaMode==='media'}" data-action="feed-media-mode" class="pati-feed-switch-btn ${feedMediaMode==='media'?'active':''}">Fotoğraf &amp; Video</button><button type="button" role="tab" aria-selected="${feedMediaMode==='text'}" data-action="feed-text-mode" class="pati-feed-switch-btn ${feedMediaMode==='text'?'active':''}">Yazılar</button></div><div class="pati-feed-follow"><button type="button" data-action="feed-all" class="${feedFilter==='new'?'active':''}">Tüm gönderiler</button><button type="button" data-action="feed-follow" class="${feedFilter==='following'?'active':''}">Takip ettiklerim</button></div><div class="pati-feed-posts">${list.length?list.map(postCard).join(''):empty(feedMediaMode==='media'?'Henüz fotoğraf veya video yok':'Henüz yazılı paylaşım yok',feedMediaMode==='media'?'İlk fotoğrafı veya videoyu sen paylaş!':'İlk yazılı paylaşımı sen oluştur!')}${pageMore.posts?`<div class="pati-load-more">${button('Daha fazla paylaşım yükle','load-more','data-id="posts"')}</div>`:''}</div>`}
function explorePage(){
const lower=v=>String(v||'').toLocaleLowerCase('tr'),q=lower(search.trim());
const matches=(...v)=>!q||v.some(x=>lower(x).includes(q));
const animalOf=p=>data.pets.find(x=>x.id===p.pet_id)?.species||p.species||'';
const sameAnimal=v=>exploreAnimal==='Tümü'||lower(v)===lower(exploreAnimal);
const likesFor=id=>data.likes.filter(x=>x.post_id===id).length;
const commentsFor=id=>data.comments.filter(x=>x.post_id===id).length;
const people=data.profiles.filter(p=>p.id!==me.id&&!blocked.has(p.id)&&matches(p.display_name,p.handle,p.city,p.bio));
const pets=data.pets.filter(p=>!blocked.has(p.owner_id)&&sameAnimal(p.species)&&matches(p.name,p.species,p.breed,profile(p.owner_id).display_name));
let posts=data.posts.filter(p=>!blocked.has(p.author_id)&&sameAnimal(animalOf(p))&&matches(p.body,animalOf(p),data.pets.find(x=>x.id===p.pet_id)?.name,profile(p.author_id).display_name,profile(p.author_id).handle));
if(exploreTab==='photos')posts=posts.filter(p=>p.image_url);
if(exploreTab==='videos')posts=posts.filter(p=>p.video_url);
posts.sort((a,b)=>exploreSort==='popular'?(likesFor(b.id)*2+commentsFor(b.id)*3-likesFor(a.id)*2-commentsFor(a.id)*3)||(new Date(b.created_at)-new Date(a.created_at)):new Date(b.created_at)-new Date(a.created_at));
const media=posts.filter(p=>p.image_url||p.video_url);
const mediaTiles=media.map(p=>'<button type="button" class="pati-explore-media" data-action="explore-open-post" data-id="'+esc(p.id)+'" aria-label="Paylaşımı aç">'+(p.image_url?'<img loading="lazy" decoding="async" src="'+esc(p.image_url)+'" alt="'+esc(cut(p.body||'Patili paylaşım',70))+'">':'<video muted playsinline preload="metadata" src="'+esc(p.video_url)+'#t=0.1"></video>')+(p.video_url?'<span class="pati-explore-video-icon">▶</span>':'')+'<span class="pati-explore-tile-stats">♥ '+likesFor(p.id)+' · '+commentsFor(p.id)+' yorum</span></button>').join('');
const peopleTiles=people.map(p=>'<article class="pati-explore-person">'+avatar(p,'m')+'<div class="pati-explore-person-name"><strong>'+esc(p.display_name)+'</strong><small>@'+esc(p.handle)+(p.city?' · '+esc(p.city):'')+'</small></div><button type="button" class="pati-explore-person-follow" data-action="follow" data-id="'+esc(p.id)+'">'+(followed.has(p.id)?'Takiptesin':'Takip et')+'</button><button type="button" class="pati-explore-person-profile" data-action="view-user" data-id="'+esc(p.id)+'" aria-label="Profili gör">›</button></article>').join('');
const petTiles=pets.map(p=>'<button class="pati-explore-pet" data-action="view-user" data-id="'+esc(p.owner_id)+'"><span class="pati-explore-pet-picture">'+(p.photo_url?'<img loading="lazy" src="'+esc(p.photo_url)+'" alt="">':'🐾')+'</span><span><strong>'+esc(p.name||'Patili dost')+'</strong><small>'+esc(p.species||'Hayvan')+(p.breed?' · '+esc(p.breed):'')+'</small></span><span>›</span></button>').join('');
const tabs=[['all','Tümü'],['photos','Fotoğraflar'],['videos','Videolar'],['users','Kullanıcılar'],['pets','Patili dostlar']];
const animals=['Tümü','Kedi','Köpek','Kuş','Balık','Tavşan','Diğer'];
const mediaTab=['all','photos','videos'].includes(exploreTab);
const textPosts=exploreTab==='all'?posts.filter(p=>!p.image_url&&!p.video_url):[];
main.innerHTML='<section class="pati-explore-head"><h1>Keşfet 🐾</h1><p>Yeni dostlar, sevimli anlar ve keşfedilecek hikâyeler.</p></section>'
+'<form class="pati-explore-search" id="pati-explore-form"><input id="explore-search" type="search" autocomplete="off" placeholder="Kullanıcı, paylaşım veya patili dost ara…" value="'+esc(search)+'" aria-label="Keşfet araması"><button type="submit" aria-label="Ara">⌕</button></form>'
+'<nav class="pati-explore-tabs" aria-label="Keşfet kategorileri">'+tabs.map(t=>'<button type="button" data-action="explore-tab" data-id="'+t[0]+'" class="'+(exploreTab===t[0]?'active':'')+'" aria-pressed="'+(exploreTab===t[0])+'">'+t[1]+'</button>').join('')+'</nav>'
+'<div class="pati-explore-filter"><div class="pati-explore-animals">'+animals.map(name=>'<button type="button" data-action="explore-animal" data-id="'+name+'" class="'+(exploreAnimal===name?'active':'')+'">'+name+'</button>').join('')+'</div>'+(mediaTab?'<button type="button" class="pati-explore-sort" data-action="explore-sort">'+(exploreSort==='popular'?'★ Popüler':'◷ En yeni')+'</button>':'')+'</div>'
+(mediaTab?'<section class="pati-explore-section"><div class="pati-explore-section-title"><h2>'+(exploreSort==='popular'?'Popüler paylaşımlar':'Fotoğraf ve videolar')+'</h2><span>'+media.length+' paylaşım</span></div>'+(media.length?'<div class="pati-explore-gallery">'+mediaTiles+'</div>':empty('Uygun fotoğraf veya video bulunamadı','Başka bir arama veya filtre deneyebilirsin.'))+'</section>':'')
+(exploreTab==='all'&&textPosts.length?'<section class="pati-explore-section"><div class="pati-explore-section-title"><h2>Yazılı paylaşımlar</h2></div>'+textPosts.slice(0,6).map(postCard).join('')+'</section>':'')
+(['all','users'].includes(exploreTab)?'<section class="pati-explore-section"><div class="pati-explore-section-title"><h2>'+(exploreTab==='users'?'Hayvanseverler':'Önerilen kullanıcılar')+'</h2></div>'+(people.length?'<div class="pati-explore-people">'+peopleTiles+'</div>':empty('Kullanıcı bulunamadı'))+'</section>':'')
+(exploreTab==='pets'?'<section class="pati-explore-section"><div class="pati-explore-section-title"><h2>Patili dostlar</h2></div>'+(pets.length?'<div class="pati-explore-pets">'+petTiles+'</div>':empty('Patili dost bulunamadı'))+'</section>':'');
}
function communityPage(){let categories=['Tümü','Genel','Sağlık','Beslenme','Eğitim','Davranış','Bakım','Diğer'];let qs=[...data.questions].filter(x=>!blocked.has(x.author_id)&&(communityCategory==='Tümü'||x.category===communityCategory)).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));main.innerHTML=header('Topluluk','Sorular, yanıtlar ve hayvansever deneyimleri.',button('+ Soru sor','question'))+`<div class="pati-filter-tabs">${categories.map(cat=>`<button type="button" data-action="community-filter" data-id="${cat}" class="${communityCategory===cat?'active':''}">${cat}</button>`).join('')}</div><div class="pati-list">${qs.map(q=>`<article class="pati-card"><div class="pati-row between">${userRow(q.author_id,day(q.created_at))}<span class="pati-pill">${esc(q.category)}</span></div><h3 style="margin-top:13px">${esc(q.title)}</h3><p>${esc(q.body)}</p><div class="pati-actionbar"><button data-action="vote" data-id="${q.id}" class="${voted.has(q.id)?'active':''}">▲ ${data.votes.filter(x=>x.question_id===q.id).length} Faydalı</button><button data-action="replies" data-id="${q.id}">💬 ${data.replies.filter(x=>x.question_id===q.id).length} cevap</button>${q.author_id===me.id?`<button class="danger" data-action="delete-question" data-id="${q.id}">Sil</button>`:`<button data-action="report" data-id="${q.id}" data-kind="question">Bildir</button>`}</div></article>`).join('')}</div>${qs.length?'':empty('Henüz soru yok','İlk soruyu sen sorabilirsin.')}`}
const knowledge=window.PATIYIZ_KNOWLEDGE||[];
function practicalGuide(a){const t=a.title.toLocaleLowerCase('tr'),sp=a.species;let urgent='Nefes almada güçlük, bayılma, nöbet, ciddi kanama veya belirgin halsizlik varsa beklemeden veteriner kliniğine başvurun.';let steps=[];
if(/kus|kusma|istifra|ishal|dışkı/.test(t)){steps=['İlk olarak ne zaman başladığını, kaç kez tekrarlandığını ve kusmuk/dışkının rengini not edin.','Hayvanın normal davranıp davranmadığını, su içmesini, iştahını ve tuvalet sıklığını izleyin.','Yabancı cisim, zehirli madde veya farklı yiyecek ihtimali varsa gecikmeden veterineri arayın.','Kendi kendinize insan ilacı, antibiyotik veya kusma ilacı vermeyin.'];urgent='Tekrarlayan kusma, kan, şiş karın, suyu tutamama, ağrı, yavru/yaşlı hayvan ya da halsizlik durumunda aynı gün veteriner desteği alın.'}
else if(/idrar|tuvalet|kum|işeme/.test(t)){steps=['Tuvalet kabını ve ortamın sessizliğini gözden geçirin; kabı günlük temizleyin.','İdrar veya dışkı sıklığında, miktarında ve zorlanmada değişiklik olup olmadığını not edin.','Evdeki tuvalet sayısını ve ulaşılabilirliği artırın; ani kum değişikliğinden kaçının.','Davranışı cezalandırmayın; ağrı veya hastalık nedenini veterinerle dışlayın.'];urgent='Özellikle kedilerde idrar yapmaya çalışıp yapamamak hayatı tehdit eden acildir; hemen veterinere gidin.'}
else if(/mama|beslen|su iç|iştah|kilo/.test(t)){steps=['Hayvanın yaşına, türüne ve sağlık durumuna uygun tam ve dengeli besin seçin.','Ölçülü porsiyon verin; ödülleri ve ek gıdaları günlük toplamdan sayın.','Yeni mamaya birkaç gün içinde kademeli geçin; dışkı, iştah ve su tüketimini izleyin.','Kilo ve vücut kondisyonunu düzenli kaydedip gerekirse veterinerle porsiyon planı oluşturun.'];urgent='24 saati aşan iştahsızlık, aşırı susama, hızlı kilo kaybı veya kusma ile birlikte yememe için veterinere başvurun; yavrularda daha erken davranın.'}
else if(/kork|stres|agres|ısır|havla|miyav|tı(r|r)|davran|eğitim/.test(t)){steps=['Davranışın başladığı anları, ortamı, sesi ve beden dilini kaydedin.','Zorlamayı ve cezalandırmayı bırakıp hayvana güvenli kaçış/dinlenme alanı sağlayın.','İstenen sakin davranışları kısa tekrarlarla ödüllendirin; tetikleyicilere aşamalı yaklaşın.','Ani değişim, ağrı şüphesi veya yaralanma riski varsa veteriner ve nitelikli davranış uzmanına danışın.'];urgent='Ani saldırganlık, ağrı, kendine zarar verme veya ciddi korku davranışı varsa sağlık nedenleri öncelikle değerlendirilmelidir.'}
else if(/zehir|toksik|çikolata|zambak|acil/.test(t)){steps=['Hayvanı tehlike kaynağından uzaklaştırın, kendi güvenliğinizi de koruyun.','Şüpheli ürünü, miktarı ve maruziyet saatini not edip ambalajı saklayın.','Hemen veterineri arayıp tür, kilo, belirtiler ve olası maddeyi iletin.','Veteriner istemedikçe kusturmayın, ağızdan ilaç/yağ/tuz vermeyin.'];urgent='Zehirlenme şüphesinde belirti başlamasını beklemeyin: hemen veterinerle görüşün.'}
else {steps=['Önce hayvanın normal rutinini, ortamını ve bu konudaki asıl değişikliği belirleyin.','Rehberdeki önerilerden bir veya ikisini güvenli biçimde uygulayın; her şeyi aynı anda değiştirmeyin.','İştah, su tüketimi, hareket, davranış ve tuvalet düzenini birkaç gün not edin.','İlerleme yoksa veya belirtiler kötüleşiyorsa veterinerden hayvanınıza özel değerlendirme isteyin.'];}
return '<div class="kb-action-plan"><h3>Adım adım ne yapmalı?</h3><ol>'+steps.map((x,i)=>'<li><strong>'+(i+1)+'. adım:</strong> '+esc(x)+'</li>').join('')+'</ol><h3>Ne zaman profesyonel destek gerekli?</h3><p>'+esc(urgent)+'</p><h3>Kontrol listesi</h3><p>İşlem sonrası gözlediğiniz değişiklikleri ve tarihlerini yazın. İyileşme yoksa ilk değerlendirmeyi tekrarlamak yerine veterinerden yardım alın.</p></div>'}
function knowledgePage(){if(articleId){const a=knowledge.find(x=>x.id===articleId);if(!a){articleId='';knowledgePage();return}const src={'merck':'https://www.merckvetmanual.com/','aspca_food':'https://www.aspca.org/pet-care/animal-poison-control/people-foods-avoid-feeding-your-pets','cat_litter':'https://www.aspca.org/pet-care/cat-care/common-cat-behavior-issues','lilies':'https://www.fda.gov/animal-veterinary/animal-health-literacy/lovely-lilies-and-curious-cats-dangerous-combination','dog_home':'https://www.rspca.org.uk/adviceandwelfare/pets/dogs'};main.innerHTML=`<button class="btn-link" data-action="knowledge-back">← Bilgi merkezine dön</button><div class="kb-article"><div class="kb-article-heading"><span class="kb-article-label">${esc(a.species)} · ${esc(a.category)}</span><h1>${esc(a.title)}</h1><p>${esc(a.excerpt)}</p></div><div class="kb-article-body"><h3>Bilmen gerekenler</h3><p>${esc(a.content)}</p><h3>Pratik öneriler</h3><ul>${(a.tips||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${practicalGuide(a)}<div class="kb-article-box">Bu bilgiler genel bilgilendirme amaçlıdır; veteriner teşhisi veya tedavisinin yerini almaz.</div><div class="kb-article-foot">${button(favorites.has(a.id)?'🔖 Kaydedildi':'🔖 Kaydet','kb-save',`data-id="${a.id}"`)}<a target="_blank" rel="noopener noreferrer" class="kb-source" href="${esc(src[a.source]||'https://www.merckvetmanual.com/')}">İlgili kaynağı incele ↗</a></div></div></div>`;return}
let list=knowledge.filter(a=>(kbFilter==='Tümü'||kbFilter==='Kaydedilenler'||a.species===kbFilter)&&((a.title+' '+a.excerpt+' '+a.category).toLocaleLowerCase('tr').includes(kbSearch.toLocaleLowerCase('tr'))));main.innerHTML=header('Hayvan Bilgi Merkezi',`${knowledge.length} bakım ve sağlık rehberi`)+`<div class="hero-online"><small>ÜCRETSİZ BİLGİ KÜTÜPHANESİ</small><h2>Daha bilinçli bir bakım için</h2><p>Kedi, köpek, kuş, tavşan, balık ve kemirgenler hakkında pratik rehberler.</p></div><div class="toolbar"><input class="input-search" id="kb-search" placeholder="Bilgi ara: mama, eğitim, sağlık..." value="${esc(kbSearch)}"><button class="soft-btn" data-action="kb-search">Ara</button></div><div class="segmented">${['Tümü','Kedi','Köpek','Kuş','Tavşan','Balık','Kemirgen','Genel','Kaydedilenler'].map(t=>`<button class="${kbFilter===t?'active':''}" data-action="kb-filter" data-id="${esc(t)}">${t}</button>`).join('')}</div><div class="knowledge-grid">${list.filter(a=>kbFilter!=='Kaydedilenler'||favorites.has(a.id)).map(a=>`<button class="knowledge-card" data-action="kb-read" data-id="${a.id}"><div class="kb-emoji">${petIcon(a.species)}</div><span class="pati-pill">${esc(a.category)}</span><strong>${esc(a.title)}</strong><p>${esc(a.excerpt)}</p></button>`).join('')}</div>${list.length?'':empty('Rehber bulunamadı')}`}
function lostPage(){const list=[...data.lost].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)).filter(x=>x.name.toLocaleLowerCase('tr').includes(search.toLocaleLowerCase('tr'))||x.city.toLocaleLowerCase('tr').includes(search.toLocaleLowerCase('tr')));main.innerHTML=header('Kayıp hayvanlar','Kayıp dostları güvenli şekilde bulmaya yardımcı ol.',button('+ İlan oluştur','lost-add'))+`<div class="pati-note">Güvenlik için yalnızca şehir / ilçe ve yaklaşık konum yayınla; açık ev adresi veya telefon numarası yazma.</div><div class="toolbar"><input id="lost-search" class="input-search" placeholder="Şehir veya isim ara" value="${esc(search)}"><button class="soft-btn" data-action="lost-search">Ara</button></div><div class="pati-list">${list.map(x=>`<article class="pati-card"><div class="pati-row between"><span class="pati-pill">${x.found?'✅ Bulundu':'📍 Kayıp'}</span><span class="meta">${day(x.last_seen)}</span></div><h3>${petIcon(x.species)} ${esc(x.name)} · ${esc(x.species)}</h3><p>📍 ${esc(x.city)} / ${esc(x.district)}</p>${x.photo_url?photo(x.photo_url):''}<p>${esc(x.description)}</p><div class="pati-actionbar">${x.owner_id===me.id?`<button data-action="toggle-found" data-id="${x.id}">${x.found?'Yeniden kayıp':'Bulundu olarak işaretle'}</button><button data-action="delete-lost" data-id="${x.id}" class="danger">İlanı sil</button>`:button('Sahibine mesaj gönder','chat',`data-id="${x.owner_id}"`)+`<button data-action="report" data-id="${x.id}" data-kind="lost">Bildir</button>`}</div></article>`).join('')}</div>${list.length?'':empty('Henüz ilan yok')}`}
function adoptionPage(){const q=search.toLocaleLowerCase('tr'),list=[...data.adoption].filter(x=>!blocked.has(x.owner_id)&&[x.name,x.species,x.city,x.district].some(t=>String(t||'').toLocaleLowerCase('tr').includes(q))).sort((a,b)=>Number(a.adopted)-Number(b.adopted)||new Date(b.created_at)-new Date(a.created_at));main.innerHTML=header('Hayvan Sahiplendirme','Patili dostlara güvenli ve sevgi dolu yuvalar bulalım.',button('+ Sahiplendirme ilanı','adoption-add'))+`<div class="pati-note">Sahiplendirme ilanları ücretsizdir. Açık adresini ve telefon numaranı herkese açık açıklamaya yazma; iletişim için Patiyiz mesajlarını kullan.</div><div class="toolbar"><input class="input-search" id="adoption-search" placeholder="Hayvan, tür veya şehir ara" value="${esc(search)}"><button class="soft-btn" data-action="adoption-search">Ara</button></div><div class="pati-list">${list.map(x=>`<article class="pati-card adoption-card"><div class="pati-row between"><span class="pati-pill">${x.adopted?'✅ Sahiplendirildi':'🐾 Yuva arıyor'}</span><small>${day(x.created_at)}</small></div><h3>${petIcon(x.species)} ${esc(x.name)} · ${esc(x.species)}</h3><p>${esc(x.gender||'Bilinmiyor')}${x.age?' · '+esc(x.age):''} · 📍 ${esc(x.city)}${x.district?' / '+esc(x.district):''}</p>${x.photo_url?photo(x.photo_url):''}<p style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(x.description)}</p><div class="pati-actionbar">${x.owner_id===me.id?button('Düzenle','adoption-edit',`data-id="${x.id}"`)+button(x.adopted?'Yeniden yayına al':'Sahiplendirildi','adoption-toggle',`data-id="${x.id}"`)+button('İlanı sil','adoption-delete',`data-id="${x.id}"`,'outline-btn'):(!x.adopted?button('İlan sahibine mesaj gönder','chat',`data-id="${x.owner_id}"`):'')}${x.owner_id!==me.id?userRow(x.owner_id)+button('İlanı bildir','report',`data-id="${x.id}" data-kind="adoption"`):''}</div></article>`).join('')}</div>${list.length?'':empty('Henüz sahiplendirme ilanı yok','İlk ilanı sen oluşturabilirsin.')}`}
function carePage(){let today=new Date().toLocaleDateString('sv-SE');let all=data.care.filter(x=>x.owner_id===me.id);let c=all.filter(x=>careFilter==='all'||(careFilter==='done'?x.done:careFilter==='late'?!x.done&&x.due_date<today:!x.done&&x.due_date>=today)).sort((a,b)=>a.due_date.localeCompare(b.due_date));main.innerHTML=header('Bakım Takvimi','Hayvanlarının önemli bakım günlerini takip et.',button('+ Görev ekle','care-add')) +`<div class="pati-filter-tabs">${[['all','Tümü'],['upcoming','Yaklaşan'],['late','Geciken'],['done','Tamamlanan']].map(([key,label])=>`<button type="button" data-action="care-filter" data-id="${key}" class="${careFilter===key?'active':''}">${label} (${all.filter(x=>key==='all'||(key==='done'?x.done:key==='late'?!x.done&&x.due_date<today:!x.done&&x.due_date>=today)).length})</button>`).join('')}</div><div class="pati-note">Bakım takvimi bu hesapta saklanır. Şu sürümde otomatik e-posta / telefon hatırlatması gönderilmez.</div><div class="pati-list">${c.map(x=>`<div class="pati-card"><div class="pati-row between"><div><span class="pati-pill">${esc(x.category)}</span><h3 style="margin-top:10px;${x.done?'text-decoration:line-through;opacity:.6':''}">${esc(x.title)}</h3><p>${day(x.due_date)} ${x.pet_id?'· '+esc(data.pets.find(p=>p.id===x.pet_id)?.name||''):''}</p></div><div class="pati-row">${button(x.done?'Yeniden aç':'✓ Tamamla','care-done',`data-id="${x.id}"`)}<button data-action="care-del" data-id="${x.id}" class="small-btn danger-btn">Sil</button></div></div></div>`).join('')}</div>${c.length?'':empty('Bakım görevi eklenmedi')}`}

let dmRecorder=null,dmParts=[],dmStream=null,dmCancel=false,dmRecipient=null;
async function uploadDmFile(file,type,receiver){if(!file?.size||file.size>8388608)throw Error('Dosya en fazla 8 MB olabilir.');const mime=file.type.split(';')[0];if(type==='image'&&!['image/jpeg','image/png','image/webp'].includes(mime))throw Error('JPG, PNG veya WebP seç.');if(type==='audio'&&!['audio/webm','audio/mp4','audio/ogg','audio/mpeg'].includes(mime))throw Error('Ses biçimi desteklenmiyor.');const ext=type==='image'?(mime==='image/png'?'png':mime==='image/webp'?'webp':'jpg'):(mime==='audio/mp4'?'m4a':mime==='audio/ogg'?'ogg':mime==='audio/mpeg'?'mp3':'webm');const path=me.id+'/'+crypto.randomUUID()+'.'+ext;const up=await sb.storage.from('patiyiz-private-messages').upload(path,file,{contentType:mime});if(up.error)throw up.error;const m=await sb.from('messages').insert({sender_id:me.id,receiver_id:receiver,body:type==='audio'?'🎤 Sesli mesaj':'📷 Fotoğraf',attachment_type:type,attachment_path:path});if(m.error)throw m.error}
async function loadDmMedia(){const images=document.querySelectorAll('[data-private-path]');await Promise.all([...images].map(async el=>{const r=await sb.storage.from('patiyiz-private-messages').createSignedUrl(el.dataset.privatePath,1800);if(!r.error&&el.isConnected)el.src=r.data.signedUrl}))}
async function sendDmImage(file){if(!personId||dmMediaSending)return;dmMediaSending=true;const recipient=personId,history=document.querySelector('.chat-history'),temp=document.createElement('div'),local=URL.createObjectURL(file);temp.className='bubble-chat mine pati-dm-pending';temp.innerHTML='<img class="pati-dm-image" alt="Gönderiliyor"><small>Gönderiliyor…</small>';temp.querySelector('img').src=local;history?.appendChild(temp);if(history)history.scrollTop=history.scrollHeight;try{await uploadDmFile(file,'image',recipient);temp.remove();await refreshKeys([['messages','messages']])}catch(e){temp.querySelector('small').textContent='Gönderilemedi';throw e}finally{URL.revokeObjectURL(local);dmMediaSending=false}}
async function startDmRecord(){if(!personId||!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('Tarayıcı ses kaydını desteklemiyor.');if(dmRecorder)return;dmStream=await navigator.mediaDevices.getUserMedia({audio:true});const type=['audio/webm;codecs=opus','audio/mp4','audio/webm','audio/ogg'].find(t=>MediaRecorder.isTypeSupported(t));if(!type){dmStream.getTracks().forEach(t=>t.stop());throw Error('Ses biçimi desteklenmiyor.')}dmParts=[];dmCancel=false;dmRecipient=personId;dmRecorder=new MediaRecorder(dmStream,{mimeType:type});dmRecorder.ondataavailable=e=>{if(e.data.size)dmParts.push(e.data)};dmRecorder.onstop=async()=>{const blob=new Blob(dmParts,{type:type.split(';')[0]});dmStream?.getTracks().forEach(t=>t.stop());dmRecorder=null;dmStream=null;document.querySelector('.pati-dm-rec-state')?.setAttribute('hidden','');if(dmCancel||!blob.size)return;try{await uploadDmFile(blob,'audio',dmRecipient);await refreshKeys([['messages','messages']])}catch(e){notify('Ses gönderilemedi: '+friendly(e),true)}};dmRecorder.start();document.querySelector('.pati-dm-rec-state')?.removeAttribute('hidden')}
function messagesPage(){
 let hiddenIds=new Set(data.messageHidden.filter(x=>x.user_id===me.id).map(x=>x.message_id));let all=data.messages.filter(x=>(x.sender_id===me.id||x.receiver_id===me.id)&&!hiddenIds.has(x.id));
 let userIds=[...new Set(all.map(x=>x.sender_id===me.id?x.receiver_id:x.sender_id).concat(personId?[personId]:[]))].filter(x=>x&&!blocked.has(x));
 userIds.sort((a,b)=>{let last=id=>Math.max(0,...all.filter(x=>x.sender_id===id||x.receiver_id===id).map(x=>new Date(x.created_at).getTime()));return last(b)-last(a)});
 if(!personId&&userIds.length)personId=userIds[0];
 let conv=all.filter(x=>(x.sender_id===me.id&&x.receiver_id===personId)||(x.sender_id===personId&&x.receiver_id===me.id)).sort((a,b)=>new Date(a.created_at)-new Date(b.created_at));
 const unreadTotal=all.filter(x=>x.receiver_id===me.id&&!x.read_at).length;
 const filteredIds=userIds.filter(id=>chatFilter==='primary'?true:chatFilter==='requests'?!followed.has(id)&&all.some(x=>x.sender_id===id&&x.receiver_id===me.id):!followed.has(id)&&!all.some(x=>x.sender_id===id&&x.receiver_id===me.id));
 const tabs=['primary','requests','general'];const labels=['Birincil','İstekler','Genel'];const chatTabs='<div class="pati-dm-filters">'+tabs.map((t,i)=>'<button type="button" data-action="dm-tab" data-id="'+t+'" class="'+(chatFilter===t?'active':'')+'">'+labels[i]+'</button>').join('')+'</div>';

 main.innerHTML='<div class="pati-dm-top"><strong>'+esc(current()?.handle||'Mesajlar')+'</strong><span>'+unreadTotal+' okunmamış</span></div>'+chatTabs+`<div class="chat-layout modern-chat pati-dm-layout ${mobileChatOpen&&personId?'mobile-chat-open':'mobile-chat-list'}"><div class="chat-people"><div class="chat-list-heading">Sohbetler <span>${filteredIds.length}</span></div>${filteredIds.map(id=>{const messages=all.filter(x=>x.sender_id===id||x.receiver_id===id).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));let last=messages[0],unread=messages.filter(x=>x.receiver_id===me.id&&!x.read_at).length;return `<button class="chat-person ${personId===id?'active':''}" data-action="chat" data-id="${esc(id)}">${avatar(profile(id),'s')}<span class="chat-person-info"><strong>${displayUser(id)}</strong><small>${last?esc(cut(last.body,80)):'Sohbete başla'}</small></span><span class="chat-person-meta"><small>${last?clock(last.created_at):''}</small>${unread?`<b class="chat-unread">${unread>99?'99+':unread}</b>`:''}</span></button>`}).join('')||`<p style="padding:17px;color:#809181">Keşfet'ten bir kullanıcıya mesaj gönderebilirsin.</p>`}</div><div class="chat-window"><header>${personId?`<button type="button" class="mobile-chat-back" data-action="chat-back" aria-label="Sohbetlere dön">←</button><span class="chat-head-avatar">${avatar(profile(personId),'s')}</span><span><strong>${displayUser(personId)}</strong><small>Özel sohbet</small></span><button type="button" data-action="view-user" data-id="${esc(personId)}" class="soft-btn chat-view-profile">Profil</button>`:'Sohbet seç'}</header><div class="chat-history">${conv.map(x=>`<div class="bubble-chat ${x.sender_id===me.id?'mine':''}" data-message-id="${esc(x.id)}" title="Silmek için basılı tut veya sağ tıkla">${x.attachment_type==='image'?'<img class="pati-dm-image" data-private-path="'+esc(x.attachment_path)+'" alt="Özel fotoğraf">':x.attachment_type==='audio'?'<audio controls class="pati-dm-audio" data-private-path="'+esc(x.attachment_path)+'"></audio>':esc(x.body)}<small>${clock(x.created_at)} · ${x.sender_id===me.id?(x.read_at?'✓✓ Okundu':'✓ Gönderildi'):day(x.created_at)}</small></div>`).join('')||'<p style="color:#95a299;text-align:center;margin:auto">Henüz mesaj yok. İlk mesajı gönder! 🐾</p>'}</div>${personId?`<form id="message-form" class="chat-form"><label class="pati-dm-camera" aria-label="Fotoğraf çek">${ico('camera')}<input type="file" name="dm_camera" accept="image/*" capture="environment" hidden></label><input name="body" placeholder="Mesaj yaz..." maxlength="1000" autocomplete="off"><button type="button" data-action="dm-record" class="pati-dm-mic" aria-label="Ses kaydet">${ico('mic')}</button><label class="pati-dm-gallery" aria-label="Galeriden fotoğraf">${ico('image')}<input type="file" name="dm_gallery" accept="image/*" hidden></label><button type="submit" class="primary-btn" aria-label="Gönder">${ico('send')}</button><div class="pati-dm-rec-state" hidden>🎙️ Ses kaydediliyor <button type="button" data-action="dm-record-stop">Gönder</button><button type="button" data-action="dm-record-cancel">İptal</button></div></form>`:''}</div></div>`;
 if(pageMore.messages){const box=main.querySelector('.chat-people');if(box)box.insertAdjacentHTML('beforeend',`<div class="pati-load-more">${button('Eski mesajları yükle','load-more','data-id="messages"')}</div>`)}const history=main.querySelector('.chat-history');if(history)history.scrollTop=history.scrollHeight;loadDmMedia();
}

function pushKeyBytes(base64){const b64=base64.replace(/-/g,'+').replace(/_/g,'/');const str=atob(b64.padEnd(Math.ceil(b64.length/4)*4,'='));return Uint8Array.from(str,c=>c.charCodeAt(0))}
async function disablePhonePush(){if(!me)throw Error('Önce giriş yapmalısın.');if(!('serviceWorker' in navigator))throw Error('Bildirim özelliği desteklenmiyor.');const reg=await navigator.serviceWorker.getRegistration('./');const sub=await reg?.pushManager?.getSubscription();if(!sub)throw Error('Bu cihazda etkin telefon bildirimi bulunmuyor.');const result=await sb.from('push_subscriptions').delete().eq('endpoint',sub.endpoint).eq('user_id',me.id);if(result.error)throw result.error;await sub.unsubscribe()}
async function enablePhonePush(){
 if(!me)return;
 if(!('serviceWorker'in navigator)||!('PushManager'in window)||!('Notification'in window)){notify('Bu tarayıcı push bildirimi desteklemiyor. iPhone için önce Safari ile Ana Ekrana Ekle kullan.',true);return}
 if(!window.PATIYIZ_PUSH_PUBLIC_KEY){notify('Bildirim sunucusu henüz kurulmadı. VAPID anahtarının eklenmesi gerekiyor.',true);return}
 try{
  const permission=await Notification.requestPermission();if(permission!=='granted'){notify('Bildirim izni verilmedi.',true);return}
  const reg=await navigator.serviceWorker.register('./patiyiz-sw.js',{scope:'./'});
  const existing=await reg.pushManager.getSubscription();
  const sub=existing||await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:pushKeyBytes(window.PATIYIZ_PUSH_PUBLIC_KEY)});
  const json=sub.toJSON();if(!json.keys?.p256dh||!json.keys?.auth)throw Error('Bildirim aboneliği oluşturulamadı.');
  const record={user_id:me.id,endpoint:sub.endpoint,p256dh:json.keys.p256dh,auth_secret:json.keys.auth};
  const saved=await sb.from('push_subscriptions').upsert(record,{onConflict:'endpoint'});
  if(saved.error)throw saved.error;
  notify('Telefon bildirimleri açıldı!');if(view==='notifications')render();
 }catch(e){console.error(e);notify('Bildirim açılamadı: '+friendly(e),true)}
}
